class Solution {

    /**
     * @param Integer[] $salary
     * @return Float
     */
    function average($salary) {
        $sum = 0;
        $minSalary = $salary[0];
        $maxSalary = $salary[0];

        foreach ($salary as $amount) {
            $sum += $amount;
            $minSalary = min($minSalary, $amount);
            $maxSalary = max($maxSalary, $amount);
        }

        return (float) ($sum - $minSalary - $maxSalary) / (count($salary) - 2);
    }
}
