    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        $mod = 100000;
        $limit = 10000000000;

        $twos = 0;
        $fives = 0;
        $suffix = 1;
        $exact = 1;

        $logSum = 0.0;
        $compensation = 0.0;

        for ($i = $left; $i <= $right; $i++) {
            // Compensated summation improves leading-digit precision.
            $term = log10($i) - $compensation;
            $next = $logSum + $term;
            $compensation = ($next - $logSum) - $term;
            $logSum = $next;

            $value = $i;
            while ($value % 2 === 0) {
                $twos++;
                $value = intdiv($value, 2);
            }
            while ($value % 5 === 0) {
                $fives++;
                $value = intdiv($value, 5);
            }

            $suffix = ($suffix * $value) % $mod;
            $exact = min($limit, $exact * $value);
        }

        $zeros = min($twos, $fives);

        // Restore only the factors that do not belong to trailing zeros.
        $factor = $twos > $fives ? 2 : 5;
        $remaining = abs($twos - $fives);

        for ($i = 0; $i < $remaining; $i++) {
            $suffix = ($suffix * $factor) % $mod;
            $exact = min($limit, $exact * $factor);
        }

        if ($exact < $limit) {
            return (string) $exact . 'e' . $zeros;
        }

        // Removing trailing zeros does not change the leading digits.
        $fraction = $logSum - floor($logSum);
        $prefix = (int) floor(pow(10, $fraction + 4));
        $lastFive = str_pad((string) $suffix, 5, '0', STR_PAD_LEFT);

        return $prefix . '...' . $lastFive . 'e' . $zeros;
    }
}
