class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Boolean
     */
    function kLengthApart($nums, $k) {
        $previous = -1;

        foreach ($nums as $index => $value) {
            if ($value === 1) {
                if ($previous !== -1 && $index - $previous <= $k) {
                    return false;
                }
                $previous = $index;
            }
        }

        return true;
    }
}
