    /**
     * @param Integer[][] $grid
     * @param Integer[][] $hits
     * @return Integer[]
     */
    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $k = count($hits);
        $removed = array_fill(0, $k, false);
        $result = array_fill(0, $k, 0);

        // Remove all directly hit bricks before processing in reverse.
        foreach ($hits as $i => $hit) {
            $r = $hit[0];
            $c = $hit[1];

            if ($grid[$r][$c] === 1) {
                $removed[$i] = true;
                $grid[$r][$c] = 0;
            }
        }

        // Mark a connected component as stable (2), counting new stable bricks.
        $stabilize = function ($r, $c) use (&$grid, $m, $n) {
            $stack = [$r * $n + $c];
            $grid[$r][$c] = 2;
            $count = 0;

            while (!empty($stack)) {
                $id = array_pop($stack);
                $r = intdiv($id, $n);
                $c = $id % $n;
                ++$count;

                if ($r > 0 && $grid[$r - 1][$c] === 1) {
                    $grid[$r - 1][$c] = 2;
                    $stack[] = $id - $n;
                }
                if ($r + 1 < $m && $grid[$r + 1][$c] === 1) {
                    $grid[$r + 1][$c] = 2;
                    $stack[] = $id + $n;
                }
                if ($c > 0 && $grid[$r][$c - 1] === 1) {
                    $grid[$r][$c - 1] = 2;
                    $stack[] = $id - 1;
                }
                if ($c + 1 < $n && $grid[$r][$c + 1] === 1) {
                    $grid[$r][$c + 1] = 2;
                    $stack[] = $id + 1;
                }
            }

            return $count;
        };

        // Find all bricks still connected to the roof.
        for ($c = 0; $c < $n; ++$c) {
            if ($grid[0][$c] === 1) {
                $stabilize(0, $c);
            }
        }

        for ($i = $k - 1; $i >= 0; --$i) {
            if (!$removed[$i]) {
                continue;
            }

            $r = $hits[$i][0];
            $c = $hits[$i][1];
            $grid[$r][$c] = 1;

            $isStable =
                $r === 0 ||
                ($r > 0 && $grid[$r - 1][$c] === 2) ||
                ($r + 1 < $m && $grid[$r + 1][$c] === 2) ||
                ($c > 0 && $grid[$r][$c - 1] === 2) ||
                ($c + 1 < $n && $grid[$r][$c + 1] === 2);

            if ($isStable) {
                // Exclude the restored brick itself.
                $result[$i] = $stabilize($r, $c) - 1;
            }
        }

        return $result;
    }
}
