class Solution {

    /**
     * @param String $s
     * @return Boolean
     */
    function areOccurrencesEqual($s) {
        $frequencies = array_fill(0, 26, 0);
        $length = strlen($s);

        for ($i = 0; $i < $length; $i++) {
            $frequencies[ord($s[$i]) - ord('a')]++;
        }

        $expected = 0;
        foreach ($frequencies as $frequency) {
            if ($frequency === 0) {
                continue;
            }

            if ($expected === 0) {
                $expected = $frequency;
            } elseif ($frequency !== $expected) {
                return false;
            }
        }

        return true;
    }
}
