class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $mod = 1000000007;
        sort($arr, SORT_NUMERIC);

        $dp = [];
        $answer = 0;
        $n = count($arr);

        for ($i = 0; $i < $n; $i++) {
            $value = $arr[$i];
            $ways = 1;

            for ($j = 0; $j < $i; $j++) {
                $left = $arr[$j];

                if ($value % $left !== 0) {
                    continue;
                }

                $right = intdiv($value, $left);

                if (isset($dp[$right])) {
                    $ways = ($ways + $dp[$left] * $dp[$right]) % $mod;
                }
            }

            $dp[$value] = $ways;
            $answer = ($answer + $ways) % $mod;
        }

        return $answer;
    }
}
