class Solution {

    /**
     * @param Integer $n
     * @return Integer
     */
    function clumsy($n) {
        $total = 0;
        $term = $n;
        $operation = 0;

        for ($value = $n - 1; $value >= 1; $value--) {
            switch ($operation) {
                case 0:
                    $term *= $value;
                    break;
                case 1:
                    $term = intdiv($term, $value);
                    break;
                case 2:
                    $total += $term;
                    $term = $value;
                    break;
                case 3:
                    $total += $term;
                    $term = -$value;
                    break;
            }

            $operation = ($operation + 1) % 4;
        }

        return $total + $term;
    }
}
