class MKAverage {
    private $m;
    private $k;
    private $size = 0;
    private $position = 0;
    private $window;
    private $counts;
    private $sums;
    private $limit = 100000;

    /**
     * @param Integer $m
     * @param Integer $k
     */
    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;
        $this->window = array_fill(0, $m, 0);
        $this->counts = array_fill(0, $this->limit + 1, 0);
        $this->sums = array_fill(0, $this->limit + 1, 0);
    }

    /**
     * @param Integer $num
     * @return NULL
     */
    function addElement($num) {
        if ($this->size === $this->m) {
            $this->update($this->window[$this->position], -1);
        } else {
            ++$this->size;
        }

        $this->window[$this->position] = $num;
        $this->update($num, 1);

        ++$this->position;
        if ($this->position === $this->m) {
            $this->position = 0;
        }
    }

    /**
     * @return Integer
     */
    function calculateMKAverage() {
        if ($this->size < $this->m) {
