    function maxPoints($points) {
        $n = count($points);
        if ($n <= 2) {
            return $n;
        }

        $best = 1;

        for ($i = 0; $i < $n; $i++) {
            if ($best >= $n - $i) {
                break;
            }

            $slopes = [];

            for ($j = $i + 1; $j < $n; $j++) {
                $dx = $points[$j][0] - $points[$i][0];
                $dy = $points[$j][1] - $points[$i][1];

                $a = abs($dx);
                $b = abs($dy);
                while ($b !== 0) {
                    $remainder = $a % $b;
                    $a = $b;
                    $b = $remainder;
