     * @param Integer $maxSize
     */
    function __construct($maxSize) {
        $this->maxSize = $maxSize;
    }

    /**
     * @param Integer $x
     * @return NULL
     */
    function push($x) {
        if (count($this->stack) >= $this->maxSize) {
            return;
        }

        $this->stack[] = $x;
        $this->pending[] = 0;
    }

    /**
     * @return Integer
     */
    function pop() {
        $top = count($this->stack) - 1;
        if ($top < 0) {
            return -1;
        }

        $increment = array_pop($this->pending);
        if ($top > 0) {
            $this->pending[$top - 1] += $increment;
        }

        return array_pop($this->stack) + $increment;
