    /**
     * @param Integer[][] $fruits
     * @param Integer $startPos
     * @param Integer $k
     * @return Integer
     */
    function maxTotalFruits($fruits, $startPos, $k) {
        $left = 0;
        $sum = 0;
        $answer = 0;
        $n = count($fruits);

        for ($right = 0; $right < $n; $right++) {
            $sum += $fruits[$right][1];
            $rightPos = $fruits[$right][0];

            while ($left <= $right) {
                $leftPos = $fruits[$left][0];

                // Reach the nearer endpoint, then traverse the interval.
                $steps = $rightPos - $leftPos
                    + min(abs($startPos - $leftPos), abs($startPos - $rightPos));

                if ($steps <= $k) {
                    break;
                }

                $sum -= $fruits[$left][1];
                $left++;
            }

            $answer = max($answer, $sum);
        }

        return $answer;
    }
}
