    /**
     * @param Integer[] $flowers
     * @param Integer $newFlowers
     * @param Integer $target
     * @param Integer $full
     * @param Integer $partial
     * @return Integer
     */
    function maximumBeauty($flowers, $newFlowers, $target, $full, $partial) {
        sort($flowers, SORT_NUMERIC);
        $n = count($flowers);

        $incomplete = 0;
        $prefix = [0];

        while ($incomplete < $n && $flowers[$incomplete] < $target) {
            $prefix[$incomplete + 1] =
                $prefix[$incomplete] + $flowers[$incomplete];
            ++$incomplete;
        }

        $best = 0;
        $budget = $newFlowers;

        // Complete the largest incomplete gardens first.
        for ($remaining = $incomplete; $remaining >= 0; --$remaining) {
            if ($budget < 0) {
                break;
            }

            $fullBeauty = ($n - $remaining) * $full;

            if ($remaining === 0) {
                $best = max($best, $fullBeauty);
                break;
            }

            // Find the largest prefix affordable to level to its maximum.
            $left = 1;
            $right = $remaining;

            while ($left < $right) {
                $mid = intdiv($left + $right + 1, 2);
                $cost = $flowers[$mid - 1] * $mid - $prefix[$mid];

                if ($cost <= $budget) {
                    $left = $mid;
                } else {
                    $right = $mid - 1;
                }
            }

            $minimum = min(
                $target - 1,
                intdiv($budget + $prefix[$left], $left)
            );

            $best = max($best, $fullBeauty + $minimum * $partial);
            $budget -= $target - $flowers[$remaining - 1];
        }

        return $best;
    }
}
