     * @param Integer[][] $graph
     * @param Integer[] $initial
     * @return Integer
     */
    function minMalwareSpread($graph, $initial) {
        $n = count($graph);
        $infected = array_fill(0, $n, false);
        $visited = array_fill(0, $n, false);
        $saved = array_fill(0, $n, 0);

        foreach ($initial as $node) {
            $infected[$node] = true;
        }

        // Find components formed only by initially uninfected nodes.
        for ($start = 0; $start < $n; $start++) {
            if ($infected[$start] || $visited[$start]) {
                continue;
            }

            $stack = [$start];
            $visited[$start] = true;
            $size = 0;
            $owner = -1; // -1: no infected neighbor; -2: multiple.

            while (!empty($stack)) {
                $node = array_pop($stack);
                $size++;

                for ($next = 0; $next < $n; $next++) {
                    if ($graph[$node][$next] == 0) {
                        continue;
                    }

                    if ($infected[$next]) {
                        if ($owner === -1) {
                            $owner = $next;
                        } elseif ($owner !== $next) {
                            $owner = -2;
                        }
                    } elseif (!$visited[$next]) {
                        $visited[$next] = true;
                        $stack[] = $next;
                    }
                }
            }

            // Removing its sole infected neighbor saves this component.
            if ($owner >= 0) {
                $saved[$owner] += $size;
            }
        }

        $answer = $initial[0];
        foreach ($initial as $node) {
            if ($saved[$node] > $saved[$answer] ||
                ($saved[$node] === $saved[$answer] && $node < $answer)) {
                $answer = $node;
            }
        }

        return $answer;
    }
}
