            }
        }

        // Any connected island can be disconnected in at most two days.
        return 2;
    }

    private function countIslands(&$grid, $m, $n) {
        $visited = array_fill(0, $m * $n, false);
        $directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
        $islands = 0;

        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                $id = $r * $n + $c;

                if ($grid[$r][$c] === 0 || $visited[$id]) {
                    continue;
                }

                if (++$islands > 1) {
                    return 2;
                }

                $visited[$id] = true;
                $stack = [$id];

                while (!empty($stack)) {
                    $current = array_pop($stack);
                    $row = intdiv($current, $n);
                    $col = $current % $n;

                    foreach ($directions as $direction) {
                        $nr = $row + $direction[0];
                        $nc = $col + $direction[1];

