    function maxCompatibilitySum($students, $mentors) {
        $m = count($students);
        $n = count($students[0]);
        $scores = array_fill(0, $m, array_fill(0, $m, 0));

        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $m; $j++) {
