        $present = [];

        foreach ($points as $point) {
            $present[$point[0] * $base + $point[1]] = true;
        }

        $n = count($points);
        $minArea = PHP_INT_MAX;

        for ($i = 0; $i < $n; $i++) {
            $x1 = $points[$i][0];
            $y1 = $points[$i][1];

            for ($j = $i + 1; $j < $n; $j++) {
                $x2 = $points[$j][0];
                $y2 = $points[$j][1];

                if ($x1 === $x2 || $y1 === $y2) {
                    continue;
                }

                $area = abs($x1 - $x2) * abs($y1 - $y2);
                if ($area >= $minArea) {
                    continue;
                }

                if (isset($present[$x1 * $base + $y2]) &&
                    isset($present[$x2 * $base + $y1])) {
                    $minArea = $area;

                    if ($minArea === 1) {
                        return 1;
                    }
                }
            }
        }

        return $minArea === PHP_INT_MAX ? 0 : $minArea;
