    /**
     * @param String $date1
     * @param String $date2
     * @return Integer
     */
    function daysBetweenDates($date1, $date2) {
        $toDays = function ($date) {
            [$year, $month, $day] = array_map('intval', explode('-', $date));

            $previousYear = $year - 1;
            $days = 365 * $previousYear
                  + intdiv($previousYear, 4)
                  - intdiv($previousYear, 100)
                  + intdiv($previousYear, 400);

            $daysBeforeMonth = [
                0, 31, 59, 90, 120, 151,
                181, 212, 243, 273, 304, 334
            ];

            $days += $daysBeforeMonth[$month - 1] + $day;

            $isLeapYear = ($year % 400 === 0)
                       || ($year % 4 === 0 && $year % 100 !== 0);

            if ($month > 2 && $isLeapYear) {
                $days++;
            }

            return $days;
        };

        return abs($toDays($date1) - $toDays($date2));
    }
}
