                if ($consecutive === $k) {
                    $bouquets++;
                    $consecutive = 0;

                    if ($bouquets >= $m) {
                        break;
                    }
                }
            }

            if ($bouquets >= $m) {
                $right = $mid;
            } else {
                $left = $mid + 1;
            }
        }

        return $left;
    }
