    function friendRequests($n, $restrictions, $requests) {
        $parent = range(0, $n - 1);
        $size = array_fill(0, $n, 1);

        $find = static function ($x) use (&$parent) {
            while ($parent[$x] !== $x) {
                $parent[$x] = $parent[$parent[$x]];
                $x = $parent[$x];
            }
            return $x;
        };

        $result = [];

        foreach ($requests as $request) {
            $rootU = $find($request[0]);
            $rootV = $find($request[1]);

            if ($rootU === $rootV) {
                $result[] = true;
                continue;
            }

            $allowed = true;

            foreach ($restrictions as $restriction) {
                $rootX = $find($restriction[0]);
                $rootY = $find($restriction[1]);

                if (($rootX === $rootU && $rootY === $rootV) ||
                    ($rootX === $rootV && $rootY === $rootU)) {
                    $allowed = false;
