    function minSessions($tasks, $sessionTime) {
        $n = count($tasks);
        $size = 1 << $n;

        // For each subset, minimize sessions first, then last-session usage.
        $sessions = array_fill(0, $size, $n + 1);
        $used = array_fill(0, $size, 0);
        $sessions[0] = 1;

        for ($mask = 1; $mask < $size; $mask++) {
            for ($i = 0; $i < $n; $i++) {
                $bit = 1 << $i;
                if (($mask & $bit) === 0) {
                    continue;
                }

                $previous = $mask ^ $bit;
                $candidateSessions = $sessions[$previous];
                $candidateUsed = $used[$previous] + $tasks[$i];

                if ($candidateUsed > $sessionTime) {
                    $candidateSessions++;
                    $candidateUsed = $tasks[$i];
                }

                if (
                    $candidateSessions < $sessions[$mask] ||
                    ($candidateSessions === $sessions[$mask] &&
                     $candidateUsed < $used[$mask])
                ) {
                    $sessions[$mask] = $candidateSessions;
                    $used[$mask] = $candidateUsed;
                }
            }
        }

        return $sessions[$size - 1];
    }
