    function medianSlidingWindow($nums, $k) {
        // Coordinate compression preserves the ordering of all values.
        $sorted = $nums;
        sort($sorted, SORT_NUMERIC);

        $values = [];
        $rank = [];
        foreach ($sorted as $value) {
            if (!isset($rank[$value])) {
                $values[] = $value;
                $rank[$value] = count($values);
            }
        }
        unset($sorted);

        $m = count($values);
        $tree = array_fill(0, $m + 1, 0);

        $step = 1;
        while (($step << 1) <= $m) {
            $step <<= 1;
        }

        $lowerOrder = intdiv($k + 1, 2);
        $upperOrder = intdiv($k + 2, 2);
        $result = [];
        $n = count($nums);

        for ($i = 0; $i < $n; $i++) {
            $this->update($tree, $m, $rank[$nums[$i]], 1);

            if ($i >= $k) {
                $this->update($tree, $m, $rank[$nums[$i - $k]], -1);
            }

            if ($i < $k - 1) {
                continue;
            }

            $left = $this->findByOrder($tree, $m, $step, $lowerOrder);

            if ($lowerOrder === $upperOrder) {
                $result[] = (float) $values[$left - 1];
            } else {
                $right = $this->findByOrder($tree, $m, $step, $upperOrder);
                $result[] = ($values[$left - 1] + $values[$right - 1]) / 2.0;
            }
        }

        return $result;
    }

    private function update(&$tree, $size, $index, $delta) {
        while ($index <= $size) {
            $tree[$index] += $delta;
            $index += $index & (-$index);
        }
    }

    // Returns the compressed rank of the requested smallest element.
    private function findByOrder(&$tree, $size, $step, $order) {
