            $node = 0;

            // Insert each word in reverse order.
            for ($i = $length - 1; $i >= 0; --$i) {
                $key = $node * 26 + ord($word[$i]) - 97;

                if (!isset($this->edges[$key])) {
                    $this->edges[$key] = $this->nodeCount++;
                }

                $node = $this->edges[$key];
            }

            $this->terminal[$node] = true;
        }
