            $u = $edge[0];
            $v = $edge[1];

            $to[] = $v;
            $next[] = $head[$u];
            $head[$u] = $edgeId++;

            $to[] = $u;
            $next[] = $head[$v];
            $head[$v] = $edgeId++;
